import com.weaver.open.gateway.entity.AuthAppEncipher;
import org.apache.commons.lang3.StringUtils;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import javax.crypto.Cipher;
import javax.crypto.spec.IvParameterSpec;
import javax.crypto.spec.SecretKeySpec;
import java.nio.charset.StandardCharsets;
import java.util.*;

public class EncipherUtils {

    private static final Logger logger = LoggerFactory.getLogger(EncipherUtils.class);

    private static final String AES = "AES";

    private static final String RSA = "RSA";

    /***
     * <h2>空校验</h2>
     * @param str 需要判断的值
     */
    public static boolean isEmpty(Object str) {
        return null == str || "".equals(str);
    }

    /***
     * <h2>String 转 byte</h2>
     * @param str 需要转换的字符串
     */
    public static byte[] getBytes(String str) {
        if (isEmpty(str)) {
            return null;
        }

        try {
            return str.getBytes(StandardCharsets.UTF_8);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    /***
     * <h2>获取一个 AES 密钥规范</h2>
     */
    public static SecretKeySpec getSecretKeySpec(String key) {
        return new SecretKeySpec(Objects.requireNonNull(getBytes(key)), "AES");
    }

    /**
     * <h2>加密 - 模式 ECB</h2>
     *
     * @param text 需要加密的文本内容
     */
    public static String encrypt(String text, AuthAppEncipher encipher) {
        try {
            if (StringUtils.isNotEmpty(encipher.getEncipherType())) {
                switch (encipher.getEncipherType()) {
                    case AES:
                        return encryptAES(text, encipher.getPrivateKey(), encipher.getEncipherOffset(), encipher.getEncipherType() + "/" +
                                encipher.getEncipherMode() + "/" + encipher.getEncipherFillIn());
                    case RSA:
                        return RSAUtil.encryptByPublicKey(encipher.getPublicKey(), text, encipher.getEncipherKeyLength());
                }
            }
            return text;
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    /**
     * 解密主入口
     *
     * @param text 需要解密的文本内容
     */
    public static String decrypt(String text, AuthAppEncipher encipher) {
        try {
            switch (encipher.getEncipherType()) {
                case AES:
                    return decryptAES(text, encipher.getPrivateKey(), encipher.getEncipherOffset(), encipher.getEncipherType() + "/" +
                            encipher.getEncipherMode() + "/" + encipher.getEncipherFillIn());
                case RSA:
                    return RSAUtil.decryptByPrivateKey(encipher.getPrivateKey(), text, encipher.getEncipherKeyLength());
                default:
                    throw new RuntimeException("参数解密异常,请检查您的加密方式是否正确");
            }
        }catch (Exception e) {
            throw new RuntimeException(e);
        }
    }


    /**
     * <h2>加密 - AES自定义加密模式</h2>
     *
     * @param text 需要加密的文本内容
     * @param key  加密的密钥 key
     * @param iv   初始化向量
     * @param mode 加密模式
     */
    public static String encryptAES(String text, String key, String iv, String mode) {
        if (isEmpty(text) || isEmpty(key)) {
            return null;
        }
        try {
            // 创建AES加密器
            Cipher cipher = Cipher.getInstance(mode);
            SecretKeySpec secretKeySpec = getSecretKeySpec(key);
            if (StringUtils.isNotEmpty(iv)) {
                cipher.init(Cipher.ENCRYPT_MODE, secretKeySpec, new IvParameterSpec(Objects.requireNonNull(getBytes(iv))));
            } else {
                cipher.init(Cipher.ENCRYPT_MODE, secretKeySpec);
            }
            // 加密字节数组
            byte[] encryptedBytes = cipher.doFinal(Objects.requireNonNull(getBytes(text)));
            // 将密文转换为 Base64 编码字符串
            return Base64.getEncoder().encodeToString(encryptedBytes);
        } catch (Exception e) {
            logger.error("encrypt data got error", e);
            throw new RuntimeException("参数解密异常,请检查您的加密方式是否正确");
        }
    }

    /**
     * <h2>解密 - 自定义加密模式</h2>
     *
     * @param text 需要解密的文本内容
     * @param key  解密的密钥 key
     * @param iv   初始化向量
     * @param mode 加密模式
     */
    public static String decryptAES(String text, String key, String iv, String mode) {
        if (isEmpty(text) || isEmpty(key)) {
            return null;
        }
        // 将密文 base64解密
        byte[] textBytes = Base64.getDecoder().decode(text);
        try {
            // 创建AES加密器
            Cipher cipher = Cipher.getInstance(mode);
            SecretKeySpec secretKeySpec = getSecretKeySpec(key);
            if (StringUtils.isNotEmpty(iv)) {
                cipher.init(Cipher.DECRYPT_MODE, secretKeySpec, new IvParameterSpec(Objects.requireNonNull(getBytes(iv))));
            } else {
                cipher.init(Cipher.DECRYPT_MODE, secretKeySpec);
            }
            // 解密字节数组
            byte[] decryptedBytes = cipher.doFinal(textBytes);
            // 将明文转换为字符串
            return new String(decryptedBytes, StandardCharsets.UTF_8);
        } catch (Exception e) {
            logger.error("decrypt data got an error ", e);
            throw new RuntimeException(e);
        }
    }


}

import cn.hutool.core.codec.Base64;
import org.apache.commons.lang3.StringUtils;

import javax.crypto.Cipher;
import java.io.ByteArrayOutputStream;
import java.nio.charset.StandardCharsets;
import java.security.KeyFactory;
import java.security.Signature;
import java.security.interfaces.RSAPrivateKey;
import java.security.interfaces.RSAPublicKey;
import java.security.spec.PKCS8EncodedKeySpec;
import java.security.spec.X509EncodedKeySpec;
import java.util.Arrays;

public class RSAUtil {

    /**
     * 加密算法RSA.
     */
    private static final String KEY_ALGORITHM = "RSA";

    /**
     * 签名算法.
     */
    private static final String SIGNATURE_ALGORITHM = "SHA1withRSA";

    /**
     * 公钥加密过程.
     *
     * @param publicKeyStr  公钥
     * @param plainTextData 明文数据
     * @return
     */
    public static String encryptByPublicKey(String publicKeyStr, String plainTextData, Integer keySize) throws Exception {
        if (StringUtils.isBlank(publicKeyStr)) {
            throw new Exception("加密公钥为空, 请设置");
        }
        try {
            return encryptByPublicKey(publicKeyStr, plainTextData.getBytes(StandardCharsets.UTF_8), keySize);
        } catch (Exception e) {
            log.error("公钥加密异常", e);
            throw new Exception("公钥加密异常");
        }
    }

    /**
     * 公钥加密过程.
     *
     * @param publicKeyStr  公钥
     * @param plainTextData 明文数据
     * @return
     */
    public static String encryptByPublicKey(String publicKeyStr, byte[] plainTextData, Integer keySize) throws Exception {
        if (StringUtils.isBlank(publicKeyStr)) {
            throw new Exception("加密公钥为空, 请设置");
        }
        try {
            return encrypt(loadPublicKeyByStr(publicKeyStr), plainTextData, keySize);
        } catch (Exception e) {
            log.error("公钥加密异常", e);
            throw new Exception("公钥加密异常");
        }
    }

    /**
     * 公钥加密过程.
     *
     * @param publicKey     公钥
     * @param plainTextData 明文数据
     * @return
     */
    public static String encrypt(RSAPublicKey publicKey, byte[] plainTextData, Integer keySize) throws Exception {
        if (publicKey == null) {
            throw new Exception("加密公钥为空, 请设置");
        }
        try {
            // 使用默认RSA
            Cipher cipher = Cipher.getInstance(KEY_ALGORITHM);
            cipher.init(Cipher.ENCRYPT_MODE, publicKey);
            byte[] dataBytes = processData(cipher, plainTextData, keySize / 8 - 11);
            return Base64.encode(dataBytes);
        } catch (Exception e) {
            log.error("公钥加密异常", e);
            throw new Exception("公钥加密异常");
        }
    }

    /**
     * 私钥解密过程.
     *
     * @param privateKeyStr 私钥
     * @param baseData      密文数据(base64加密)
     * @return 明文
     * @throws Exception 解密过程中的异常信息
     */
    public static String decryptByPrivateKey(String privateKeyStr, String baseData, Integer keySize) throws Exception {
        if (StringUtils.isBlank(privateKeyStr)) {
            throw new Exception("解密私钥为空, 请设置");
        }
        try {
            return decryptByPrivateKey(privateKeyStr, Base64.decode(baseData), keySize);
        } catch (Exception e) {
            log.error("私钥解密异常", e);
            throw new Exception("私钥解密异常");
        }
    }

    /**
     * 私钥解密过程.
     *
     * @param privateKeyStr 私钥
     * @param cipherData    密文数据
     * @return 明文
     * @throws Exception 解密过程中的异常信息
     */
    public static String decryptByPrivateKey(String privateKeyStr, byte[] cipherData, Integer keySize) throws Exception {
        if (StringUtils.isBlank(privateKeyStr)) {
            throw new Exception("解密私钥为空, 请设置");
        }
        try {
            // 获取私钥
            RSAPrivateKey privateKey = loadPrivateKeyByStr(privateKeyStr);
            return decrypt(privateKey, cipherData, keySize);
        } catch (Exception e) {
            log.error("私钥解密异常", e);
            throw new Exception("私钥解密异常");
        }
    }

    /**
     * 私钥解密过程.
     *
     * @param privateKey 私钥
     * @param cipherData 密文数据
     * @return 明文
     * @throws Exception 解密过程中的异常信息
     */
    public static String decrypt(RSAPrivateKey privateKey, byte[] cipherData, Integer keySize) throws Exception {
        if (privateKey == null) {
            throw new Exception("解密私钥为空, 请设置");
        }
        try {
            // 使用默认RSA
            Cipher cipher = Cipher.getInstance(KEY_ALGORITHM);
            cipher.init(Cipher.DECRYPT_MODE, privateKey);
            byte[] bytes = processData(cipher, cipherData, keySize / 8);
            return new String(bytes);
        } catch (Exception e) {
            log.error("私钥解密异常", e);
            throw new Exception("私钥解密异常");
        }
    }

    /**
     * 从字符串中加载公钥.
     *
     * @param publicKeyStr 公钥数据字符串
     * @return
     */
    private RSAPublicKey loadPublicKeyByStr(String publicKeyStr) throws Exception {
        try {
            byte[] buffer = Base64.decode(publicKeyStr);
            KeyFactory keyFactory = KeyFactory.getInstance(KEY_ALGORITHM);
            X509EncodedKeySpec keySpec = new X509EncodedKeySpec(buffer);
            return (RSAPublicKey) keyFactory.generatePublic(keySpec);
        } catch (Exception e) {
            log.error("公钥异常", e);
            throw new Exception("公钥异常");
        }
    }

    /**
     * 获取 私钥.
     *
     * @param privateKeyStr 私钥数据字符串
     * @throws Exception 加载私钥时产生的异常
     */
    private RSAPrivateKey loadPrivateKeyByStr(String privateKeyStr) throws Exception {
        try {
            byte[] buffer = Base64.decode(privateKeyStr);
            PKCS8EncodedKeySpec keySpec = new PKCS8EncodedKeySpec(buffer);
            KeyFactory keyFactory = KeyFactory.getInstance(KEY_ALGORITHM);
            return (RSAPrivateKey) keyFactory.generatePrivate(keySpec);
        } catch (Exception e) {
            log.error("私钥异常", e);
            throw new Exception("私钥异常");
        }
    }

    /**
     * 分段处理数据.
     *
     * @param cipher      密码算法
     * @param dataes      数据
     * @param segmentSize 分段大小（小于等于0不分段）
     * @return
     */
    private byte[] processData(Cipher cipher, byte[] dataes, int segmentSize) {
        byte[] decBytes = null;
        try {
            ByteArrayOutputStream out = new ByteArrayOutputStream();
            int inputLength = dataes.length;
            int offSet = 0;
            for (int i = 0; inputLength - offSet > 0; offSet = i * segmentSize) {
                byte[] cache;
                if (inputLength - offSet > segmentSize) {
                    cache = cipher.doFinal(dataes, offSet, segmentSize);
                } else {
                    cache = cipher.doFinal(dataes, offSet, inputLength - offSet);
                }
                out.write(cache, 0, cache.length);
                ++i;
            }
            decBytes = out.toByteArray();
            out.close();
        } catch (Exception e) {
            log.error("分段处理数据异常", e);
        }
        return decBytes;
    }

}
